  replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(lower(d.name),' ',''),'.',''),'-',''),'''',''),'&',''),'_',''),'/',''),'(',''),')',''),',','') AS name_key,rtrim(CASE WHEN substr(replace(replace(lower(trim(coalesce(d.website,''))),'https://',''),'http://',''),1,4)='www.' THEN substr(replace(replace(lower(trim(coalesce(d.website,''))),'https://',''),'http://',''),5) ELSE replace(replace(lower(trim(coalesce(d.website,''))),'https://',''),'http://','') END,'/') AS website_host FROM research_fund_directory d) f
  WHERE NOT EXISTS (SELECT 1 FROM research_fund_sources s WHERE s.source_name=f.source_name AND s.verdict='not allowed')
  AND (f.website_host='ignia.vc' OR f.website_host GLOB 'ignia.vc[/?#:]*' OR f.website_host='ignia.vc.' OR f.website_host GLOB 'ignia.vc.[/?#:]*'
    OR f.name_key IN ('ignia')
    OR EXISTS (SELECT 1 FROM (SELECT value AS base FROM json_each('["ignia"]')
      UNION ALL SELECT value || 'fund' AS base FROM json_each('["ignia"]')) n
      WHERE substr(f.name_key,1,length(n.base))=n.base
      AND ((length(substr(f.name_key,length(n.base)+1)) BETWEEN 1 AND 7 AND substr(f.name_key,length(n.base)+1) NOT GLOB '*[^ivx]*')
        OR (length(substr(f.name_key,length(n.base)+1)) BETWEEN 1 AND 2 AND substr(f.name_key,length(n.base)+1) NOT GLOB '*[^0-9]*'))
      AND substr(f.display_name,-(length(substr(f.name_key,length(n.base)+1))+1))=' ' || substr(f.name_key,length(n.base)+1))))
AND NOT EXISTS (SELECT 1 FROM research_fund_directory_uid_moves WHERE old_uid='global-ignia');

